static std::string Utf8(const std::wstring& s){int n=WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),nullptr,0,nullptr,nullptr);std::string result(n,0);if(n)WideCharToMultiByte(CP_UTF8,0,s.data(),(int)s.size(),result.data(),n,nullptr,nullptr);return result;}
static void Init(IContextMenu* context,HMENU menu,int index){IContextMenu3* third=nullptr;if(SUCCEEDED(context->QueryInterface(IID_PPV_ARGS(&third)))){LRESULT result=0;third->HandleMenuMsg2(WM_INITMENUPOPUP,(WPARAM)menu,MAKELPARAM(index,FALSE),&result);third->Release();return;}IContextMenu2* second=nullptr;if(SUCCEEDED(context->QueryInterface(IID_PPV_ARGS(&second)))){second->HandleMenuMsg(WM_INITMENUPOPUP,(WPARAM)menu,MAKELPARAM(index,FALSE));second->Release();}}
static void Scan(IContextMenu* context,HMENU menu,std::ostringstream& report,int depth,UINT& zip){for(int i=0;i<GetMenuItemCount(menu);i++){wchar_t text[1024]{};MENUITEMINFOW item{};item.cbSize=sizeof(item);item.fMask=MIIM_STRING|MIIM_ID|MIIM_SUBMENU|MIIM_STATE;item.dwTypeData=text;item.cch=1024;if(!GetMenuItemInfoW(menu,i,TRUE,&item))continue;std::wstring label=text;report<<std::string(depth*2,' ')<<Utf8(label)<<" ["<<item.wID<<"]\n";if(label.find(L"Compress to ZIP")!=std::wstring::npos)zip=item.wID;if(item.hSubMenu&&depth<5&&(depth>0||label.find(L"Xiaoma Compress")!=std::wstring::npos)){Init(context,item.hSubMenu,i);Scan(context,item.hSubMenu,report,depth+1,zip);}}}
int wmain(int argc,wchar_t** argv){if(argc<3)return 2;CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);PIDLIST_ABSOLUTE full=nullptr;IShellFolder* parent=nullptr;PCUITEMID_CHILD child=nullptr;IContextMenu* context=nullptr;HMENU menu=nullptr;std::ostringstream report;HRESULT status=SHParseDisplayName(argv[1],nullptr,&full,0,nullptr);if(SUCCEEDED(status))status=SHBindToParent(full,IID_PPV_ARGS(&parent),&child);if(SUCCEEDED(status))status=parent->GetUIObjectOf(nullptr,1,&child,IID_IContextMenu,nullptr,(void**)&context);UINT zip=0;if(SUCCEEDED(status)){menu=CreatePopupMenu();status=context->QueryContextMenu(menu,0,1,0x7fff,CMF_NORMAL);if(SUCCEEDED(status)){Scan(context,menu,report,0,zip);report<<"ZIP_COMMAND_ID="<<zip<<"\n";if(argc>=4&&std::wstring(argv[3])==L"invoke"&&zip){CMINVOKECOMMANDINFOEX command{};command.cbSize=sizeof(command);command.fMask=CMIC_MASK_UNICODE|CMIC_MASK_NOASYNC;command.lpVerb=MAKEINTRESOURCEA(zip-1);command.lpVerbW=MAKEINTRESOURCEW(zip-1);command.nShow=SW_HIDE;status=context->InvokeCommand((CMINVOKECOMMANDINFO*)&command);report<<"INVOKE_HRESULT="<<(unsigned long)status<<"\n";}}}report<<"HRESULT="<<(unsigned long)status<<"\n";std::ofstream out(argv[2],std::ios::binary);out<<report.str();if(menu)DestroyMenu(menu);if(context)context->Release();if(parent)parent->Release();if(full)CoTaskMemFree(full);CoUninitialize();return SUCCEEDED(status)&&zip?0:1;}
